function isWrongStarterPrinting(c){return !!HIDDEN_STARTER_PRINTINGS[c.set]?.has(c.id)}
function rebuild(){migrateAliases();let cc=normalizeCatalog(window.FW_CATALOG);if(state.catalogOverride){try{cc=mergeCatalog(cc,normalizeCatalog(state.catalogOverride))}catch(e){console.error(e)}}catalog=cc;sets=cc.sets;const custom=state.localCards.filter(x=>!cc.cards.some(c=>c.id===x.id));cards=[...cc.cards,...custom];const canonical=new Map(window.FW_CATALOG.cards.map(c=>[c.id,c]));cards=cards.map(c=>{const v=canonical.get(c.id);return v?{...c,set:v.set,print_label:v.print_label||c.print_label,print_origin:v.print_origin||c.print_origin}:c});const order=new Map(sets.map((s,i)=>[s.id,i]));cards.sort((a,b)=>(order.get(a.set)??999)-(order.get(b.set)??999)||(parseInt(a.number.split('-').pop(),10)||0)-(parseInt(b.number.split('-').pop(),10)||0)||(a.variant==='NORMAL'?-1:b.variant==='NORMAL'?1:0)||a.id.localeCompare(b.id));cards=cards.filter(c=>!window.FW_CATALOG.aliases?.[c.id]&&!isWrongStarterPrinting(c));cardById=new Map(cards.map(c=>[c.id,c]));if(!sets.some(s=>s.id===selectedSet))selectedSet=sets[0]?.id||''}
function toast(t){const el=$('toast');el.textContent=t;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true},2700)}function notify(t){toast(t)}
function applySeed(){if(state.seedApplied)return;const data=window.FW_SEED;state.ownedIds=unique([...state.ownedIds,...data.owned_ids.filter(id=>cardById.has(id))]);state.preimport=data.unresolved||[];state.seedApplied=true;save()}
// v1.8.2: card double-tap marks/unmarks ownership; a single card tap opens details after the
// double-tap window. Check buttons still require two taps. No collection changes on scrolling.
const DOUBLE_TAP_MS=520;
let pendingCardTap=null,pendingCardTimer=null;
function clearPendingCard(){
 if(pendingCardTimer!==null)clearTimeout(pendingCardTimer);
 pendingCardTimer=null;
 pendingCardTap?.el?.classList?.remove('tap-armed');
 pendingCardTap=null;
}
function requestCardTap(id,el,kind){
 if(!cardById.has(id))return;
 const now=performance.now();
 if(pendingCardTap&&pendingCardTap.id===id&&now-pendingCardTap.at<=DOUBLE_TAP_MS){
  clearPendingCard();changeOwned(id);return;
 }
 clearPendingCard();
 pendingCardTap={id,at:now,el,kind};
 el?.classList?.add('tap-armed');
 pendingCardTimer=setTimeout(()=>{
  const pending=pendingCardTap;
  if(!pending||pending.id!==id||pending.el!==el)return;
  clearPendingCard();
  if(kind==='detail'&&el.isConnected)openDetail(id);
 },DOUBLE_TAP_MS+50);
}
function changeOwned(id){if(!cardById.has(id))return;const had=isOwned(id);if(had){state.ownedIds=state.ownedIds.filter(x=>x!==id);state.quantities[id]=0}else{state.ownedIds.push(id);state.quantities[id]=1;if(!state.unbackedAdds.includes(id))state.unbackedAdds.push(id)}save();render();toast(had?'Als fehlend markiert':'✓ Karte vorhanden')}
function toggleHeart(id){state.favorites=isFav(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();toast(isFav(id)?'Auf die Wunschliste gesetzt':'Von Wunschliste entfernt')}
function visibleCards(){let v=cards;if(view==='collection')v=v.filter(c=>c.set===selectedSet);if(view==='missing')v=v.filter(c=>!isOwned(c.id));if(view==='wishlist')v=v.filter(c=>isFav(c.id));if(view==='missing'||view==='wishlist')v=v.filter(c=>(category==='Alle'||sets.some(s=>s.id===c.set&&s.category===category))&&(selectedSet==='ALL'||c.set===selectedSet));if(search.trim()){let q=search.toLocaleLowerCase().trim();v=v.filter(c=>[c.number,c.name,c.set,c.id].some(t=>t.toLocaleLowerCase().includes(q)))}if(ownedFilter==='owned')v=v.filter(c=>isOwned(c.id));if(ownedFilter==='missing')v=v.filter(c=>!isOwned(c.id));if(variantFilter==='alt')v=v.filter(c=>c.variant!=='NORMAL');if(variantFilter==='normal')v=v.filter(c=>c.variant==='NORMAL');if(rarityFilter!=='all')v=v.filter(c=>(c.rarity||'unbekannt')===rarityFilter);if(typeFilter!=='all')v=v.filter(c=>(c.type||'unbekannt')===typeFilter);return v}
