function dash(){
 const t=countStat(cards),v=valueTotals(),owned=cards.filter(c=>isOwned(c.id));
 const copies=owned.reduce((sum,c)=>sum+quantity(c.id),0);
 const top=owned.filter(c=>unitPrice(c.id)!==null).sort((a,b)=>unitPrice(b.id)-unitPrice(a.id)||a.id.localeCompare(b.id)).slice(0,3);
 const podium=[top[1],top[0],top[2]].map((c,i)=>{
 const rank=[2,1,3][i],height=['second','first','third'][i];
 if(!c)return `<div class="fw-step ${height}"><div class="fw-empty">Noch keine Karte mit Preis</div><div class="fw-plinth">#${rank}</div></div>`;
 const img=cardImage(c);
 return `<button class="fw-step ${height}" data-action="detail" data-id="${escapeHtml(c.id)}" aria-label="Platz ${rank}: ${escapeHtml(c.name)}"><div class="fw-rank">${rank}</div><div class="fw-cardart">${img?`<img src="${escapeHtml(img)}" alt="${escapeHtml(c.name)}" loading="lazy" onerror="this.style.display='none'">`:''}</div><div class="fw-cardlabel"><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.number)}</small><b>${money(unitPrice(c.id))}</b></div><div class="fw-plinth">#${rank}</div></button>`}).join('');
 return `<div class="page-heading be-dashboard-heading"><h1>Dashboard</h1><button class="be-add-button" data-action="openBoosterEntry" aria-label="Karten hinzufügen" title="Karten hinzufügen">+</button></div>${backupPrompt()}
 <section class="fw-compact panel"><div class="fw-summarytop"><div><span class="summary-label">ERFASSTER KARTENBESTAND</span><div class="fw-count"><b>${t.owned}</b><span>/ ${t.total}</span></div></div><strong class="fw-percent">${percent(t.owned,t.total)} %</strong></div>${bar(t.owned,t.total)}
 <div class="fw-smallstats"><span>Normal <b>${t.baseOwned} / ${t.base}</b></span><span>ALT <b>${t.altsOwned} / ${t.alts}</b></span><span>Exemplare <b>${copies}</b></span></div>
 <div class="fw-valuebar"><div><small>Wert ohne Dubletten</small><b>${money(v.single)}</b></div><div><small>Inkl. Dubletten</small><b>${money(v.total)}</b></div></div>
 ${v.priced<v.count?`<p class="fw-pricehint">Teilwerte: ${v.count-v.priced} Varianten ohne Preis</p>`:''}</section>
 <section class="fw-podiumblock"><div class="fw-podiumtitle"><h2>Top 3 wertvollste Karten</h2><span>Marktwert · USD</span></div><div class="fw-podium">${podium}</div></section>`;
}
