function variantLabel(c){return c.print_label||(c.variant==='NORMAL'?'Normal':'ALT '+(c.id.split('#ALT-')[1]||''))}
function heart(c){const fav=isFav(c.id);return `<button type="button" data-action="favorite" data-id="${escapeHtml(c.id)}" class="heart corner-heart ${fav?'is-fav':''}" aria-pressed="${fav}" aria-label="${escapeHtml(c.number)}: Wunschliste ${fav?'entfernen':'hinzufügen'}">${fav?'♥':'♡'}</button>`}
function cardImage(c){return safeImage(state.imageOverrides[c.id]||c.image)}
function priceMeta(id){const a=state.prices[id],b=state.marketPrices?.[id];return a&&typeof a.amount==='number'?{...a,manual:true}:b&&typeof b.amount==='number'?{...b,manual:false}:null}
function unitPrice(id){const v=priceMeta(id)?.amount;return typeof v==='number'&&Number.isFinite(v)&&v>=0?v:null}
function marketCoverage(){const total=Object.keys(state.marketPrices||{}).filter(id=>cardById.has(id)).length;return total}

function money(n){return new Intl.NumberFormat('de-DE',{style:'currency',currency:'USD'}).format(n)}
function priceText(id){const p=unitPrice(id);return p===null?'—':money(p)}
function listCards(v){return `<div class="card-list">${v.map(c=>`<div class="card-row ${c.variant!=='NORMAL'?'alt':''} ${isOwned(c.id)?'is-owned':''}"><button class="check ${isOwned(c.id)?'yes':''}" data-action="owned" data-id="${escapeHtml(c.id)}" aria-label="Besitz ändern: zweimal tippen" aria-pressed="${isOwned(c.id)}">${isOwned(c.id)?'✓':''}</button><button class="card-info" data-action="detail" data-id="${escapeHtml(c.id)}"><span class="card-number">${escapeHtml(c.number)} <b>×${quantity(c.id)}</b> <span class="unit-price">${priceText(c.id)}</span> ${c.variant!=='NORMAL'?'<span class="tag">'+escapeHtml(variantLabel(c))+'</span>':''}</span><span class="card-name">${escapeHtml(c.name)}</span></button>${heart(c)}</div>`).join('')}</div>`}
function galleryCards(v,forceCols){return `<div class="gallery columns-${forceCols||state.gridColumns}">${v.map(c=>{const img=cardImage(c);return `<div class="gal-item ${isOwned(c.id)?'is-owned':''}"><button type="button" style="--setcolor:${safeColor(sets.find(s=>s.id===c.set)?.color)}" class="gal-card ${c.variant!=='NORMAL'?'alt':''} ${isOwned(c.id)?'is-owned':''}" data-action="detail" data-id="${escapeHtml(c.id)}" aria-label="${escapeHtml(c.number+' '+c.name)}: Details, ${quantity(c.id)} vorhanden">${img?`<img loading="lazy" alt="${escapeHtml(c.name)}" src="${escapeHtml(img)}" onerror="this.style.display='none';this.parentElement.classList.add('img-failed')">`:''}<span class="gal-symbol">${escapeHtml(c.set)}</span><span class="gal-hint">${c.variant!=='NORMAL'?'ALT ART':'NORMAL'}</span><span class="gal-name">${escapeHtml(c.name)}</span></button>${heart(c)}<div class="compact-status ${isOwned(c.id)?'owned':''}" aria-label="${isOwned(c.id)?'Vorhanden':'Fehlt'}">${isOwned(c.id)?'✓':'○'}</div><div class="gal-caption"><span>${escapeHtml(c.number)}</span><b>×${quantity(c.id)}</b><small class="gal-unit-price">${priceText(c.id)}</small></div>${c.variant!=='NORMAL'?'<span class="compact-variant">'+escapeHtml(variantLabel(c))+'</span>':''}${state.gridColumns===2?`<div class="tile-price">${priceText(c.id)}</div>`:''}</div>`}).join('')}</div>`}
(function(){if(typeof document.createElement!=='function')return;const st=document.createElement('style');st.textContent=".collection-search-icon{flex:0 0 47px;width:47px;height:47px;display:grid;place-items:center;background:linear-gradient(155deg,#f6a34e,#943a25);color:white;border:1px solid #f7c079;border-radius:13px;font-size:35px;line-height:1;cursor:pointer;box-shadow:0 4px 15px #ef8c3e30}.page-heading .collection-search-icon{margin-left:auto}";document.head.appendChild(st)})();
function cardsPage(){const title=view==='collection'?'Meine Sammlung':view==='missing'?'Fehlende Karten':'Wunschliste';const set=sets.find(s=>s.id===selectedSet),setCards=cards.filter(c=>c.set===selectedSet),st=countStat(setCards),v=visibleCards();let s=`<div class="page-heading"><div><span class="label">FUSION WORLD COLLECTOR</span><h1>${title}</h1></div><button type="button" class="collection-search-icon" data-action="openFilters" aria-label="Filter und Suche öffnen" title="Filter und Suche">⌕</button></div>${backupPrompt()}${selectWidget()}`;
 if(view==='collection'&&set){s+=`<div class="set-banner" style="--setcolor:${safeColor(getPack(set.id).accent||set.color)}"><div class="banner-lines" aria-hidden="true"></div>${packVisual(set.id)}<div class="banner-copy"><span class="label">${escapeHtml(set.category).toUpperCase()} · ${escapeHtml(set.id)}</span><div class="banner-figure-name">${escapeHtml(getPack(set.id).figure)}</div><strong>${escapeHtml(set.name)}</strong><p>${st.owned} von ${st.total} erfassten Varianten</p>${set.complete?`${bar(st.owned,st.total)}<div class="description">Normal ${st.baseOwned}/${st.base}${st.baseOwned===st.base?' ✓':''} · ALT ${st.altsOwned}/${st.alts}${st.alts===st.altsOwned?' ✓':''} ${st.owned===st.total?'· Vollständig ✓':''}</div>`:`<div class="description">⚠ Teilkatalog: Noch keine aussagekräftige Set-Vollständigkeit. Weitere Einträge können importiert werden.</div>`}</div></div>`}
 s+='';
 if(!v.length){s+=`<div class="empty"><span style="font-size:40px">${view==='wishlist'?'♡':'◎'}</span><strong>Keine Karten gefunden</strong><p>${view==='wishlist'?'Tippe bei einer Karte auf das Herz.':'Ändere die Filter oder wähle ein anderes Set.'}</p><button class="btn" data-action="clearFilters">Filter zurücksetzen</button></div>`}else {const subset=v.slice(0,visibleLimit);s+=view==='collection'?galleryCards(subset,3):(mode==='gallery'?galleryCards(subset):listCards(subset));if(v.length>subset.length)s+=`<div class="load-more"><p>${subset.length} von ${v.length} Karten angezeigt</p><button class="btn primary" data-action="showMore">Weitere 90 anzeigen ↓</button></div>`;}
 return s}
function settingsPage(){const pending=state.preimport||[];return `<div class="settings-page"><div class="page-heading"><div><span class="label">LOKAL · DEIN GERÄT</span><h1>Einstellungen</h1></div></div>${backupPrompt()}<div class="panel"><h3>💾 Backup deiner Sammlung</h3><p>Bestand, Stückzahlen, Preise, Käufe, Bilderzuordnungen, Wunschliste, eigene Karten und der Katalog werden als JSON gesichert. Erinnerung nach 25 verschiedenen neu markierten Karten.</p><div class="btn-row"><button class="btn primary" data-action="export">Backup exportieren</button><button class="btn" data-action="importBackup">Backup importieren</button></div><p>Letzter Export: ${escapeHtml(state.lastBackup?new Date(state.lastBackup).toLocaleString('de-DE'):'noch keiner')} · Neue Markierungen: ${state.unbackedAdds.length}/25</p></div><div class="panel"><h3>💲 Marktpreise · TCGplayer</h3><p>Quelle: TCGplayer Market Price (USD), importiert über TCGCSV. Die Werte sind Marktschätzungen und keine garantierten Verkaufspreise. Manuelle Einzelpreise haben Vorrang.</p><p><b>${marketCoverage()} von ${cards.length} Katalogvarianten mit Marktpreis</b> · Preisstand: ${escapeHtml(state.marketPriceUpdated||'nicht vorhanden')}</p><p>${escapeHtml(state.marketPriceStats?.note||'Noch keine Marktpreise geladen. Fehlende Werte bleiben unbekannt, nicht $0.')}</p><div class="btn-row"><button class="btn primary" data-action="importPrices">Preisdatei importieren</button><button class="btn" data-action="clearMarketPrices">Marktpreise löschen</button></div><label class="field"><span class="small">Optionale externe Preis-URL · bei GitHub Pages automatisch auf ./prices.json gesetzt</span><input id="priceFeedUrl" type="url" placeholder="https://.../prices.json" value="${escapeHtml(state.marketPriceUrl||autoPriceFeedUrl())}"></label><div class="btn-row"><button class="btn" data-action="savePriceFeed">Adresse speichern</button><button class="btn" data-action="updateMarketPrices">Preise aktualisieren</button></div><p class="small">Ein automatischer Tagesabruf funktioniert nur von einer entsprechend gehosteten JSON-Datei. TCGCSV selbst blockiert den direkten Browserzugriff. <a href="https://tcgcsv.com/" target="_blank" rel="noopener noreferrer">TCGCSV ↗</a> · <a href="https://www.tcgplayer.com/categories/trading-and-collectible-card-games/dragon-ball-super-fusion-world/price-guides" target="_blank" rel="noopener noreferrer">TCGplayer Preisführer ↗</a></p></div><div class="panel"><h3>📦 Katalog</h3><p>Katalogdatenstand ${escapeHtml(catalog.version)} (unabhängig von App-Version 1.8.3) · ${cards.length} Varianten in ${sets.length} Gruppen. FS01–FS12 mit Basislisten/ALT-Slots; Booster/Promo mit geprüften Grundkarten-Nummernreihen, aber noch unvollständigen Variantenlisten.</p><div class="btn-row"><button class="btn" data-action="importCatalog">Katalogdatei importieren</button><button class="btn" data-action="addCard">+ Karte ergänzen</button></div><label class="field"><span class="small">Adresse einer versionierten Katalog-JSON-Datei (optional, HTTPS mit CORS)</span><input id="feedUrl" type="url" placeholder="https://.../catalog.json" value="${escapeHtml(state.remoteUrl||'')}"></label><div class="btn-row"><button class="btn" data-action="saveFeed">Adresse speichern</button><button class="btn" data-action="checkUpdates">Updates prüfen</button></div><p>Automatische Prüfung maximal einmal täglich nach Einrichten einer URL. Wir verwenden keine unbestätigte Bandai-API. Besitzhaken bleiben unverändert.</p></div><div class="panel"><h3>🖼 Offline-Bilder</h3><p>Für alle zwölf Starter sowie für zahlreiche Booster und Promos sind externe Bildadressen hinterlegt. Bildlinks sind nicht alle überprüft; nicht verfügbare Motive zeigen Platzhalter. Die Bilder benötigen Internet und können vom Anbieter blockiert werden.</p><button class="btn" data-action="cacheSet">Onlinebilder dieses Sets offline speichern (Test)</button><p>Ausgewähltes Set: ${escapeHtml(selectedSet)}. Der Offline-Download setzt HTTPS und die Freigabe des Bildanbieters (CORS) voraus; er kann scheitern. Bildrechte verbleiben beim jeweiligen Rechteinhaber.</p></div><div class="panel"><h3>🔎 Import-Kontrolle</h3><p>Der bisherige Besitz wurde aus unserem Sammelprotokoll übernommen. Bei geöffneten Decks sind die normalen Karten als vorhanden abgeleitet worden. Diese Zuordnung kannst du in der Sammlung einzeln korrigieren.</p>${pending.map(x=>`<p>• <b>${escapeHtml(x.context)}</b>: ${escapeHtml(x.note)}</p>`).join('')}<p>Speicher: ${storageMode==='indexeddb'?'IndexedDB':storageMode==='localstorage'?'localStorage (Fallback)':'nur temporär – Backup dringend empfohlen'}</p></div><div class="panel"><h3>Quellen und Grenzen</h3><p>Starter nach offizieller Fusion World Card Database. Booster: veröffentlichte Setzählungen und ausgewählte Namens-/ALT-Listen. Promotion Cards: öffentliches Promo-Verzeichnis. Verlinkte Bilder: DotGG (ohne Bilddateien im Download). Für eine dauerhafte öffentliche Weiterverbreitung sind Nutzungsrechte zu klären.</p><p><a href="https://www.dbs-cardgame.com/fw/en/cardlist/" rel="noopener noreferrer" target="_blank">Offizielle Karten-Datenbank ↗</a> · <a href="https://dragonball.gg/cards/" target="_blank" rel="noopener noreferrer">Quelle der Test-Kartenbilder ↗</a></p></div></div>`}
function shell(content){$('screen').innerHTML=content;document.querySelectorAll('.bottom-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===view)})}
function render(){if(!state)return;applyTheme();shell(view==='booster'?boosterPage():view==='dashboard'?dash():view==='settings'?settingsPage():view==='value'?valuePage():cardsPage())}
function go(tab){clearPendingCard();visibleLimit=90;view=tab;if(tab==='collection'&&selectedSet==='ALL')selectedSet=sets.find(s=>s.category===category)?.id||'FS01';if(tab==='missing'||tab==='wishlist'){category='Alle';selectedSet='ALL'}search='';ownedFilter='all';variantFilter='all';rarityFilter='all';typeFilter='all';render();scrollTo({top:0,behavior:'instant'})}
function fileInput(accept,callback){const input=$('fileInput');input.value='';input.accept=accept;input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{await callback(JSON.parse(await file.text()))}catch(e){notify('Datei nicht übernommen: '+e.message)}};input.click()}
function downloadJson(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function doBackup(){const now=new Date().toISOString();const backup={kind:'fusion-world-collector-backup',schema_version:1,created_at:now,quantities:state.quantities,prices:state.prices,marketPrices:state.marketPrices,marketPriceUpdated:state.marketPriceUpdated,marketPriceUrl:state.marketPriceUrl,marketPriceChecked:state.marketPriceChecked,marketPriceStats:state.marketPriceStats,imageOverrides:state.imageOverrides,purchases:state.purchases,gridColumns:state.gridColumns,ownedIds:state.ownedIds,favorites:state.favorites,localCards:state.localCards,unbackedAdds:[],catalogSnapshot:catalog,preimport:state.preimport};downloadJson(`Fusion_World_Backup_${now.slice(0,10)}.json`,backup);state.lastBackup=now;state.unbackedAdds=[];save();render();notify('Backup-Download gestartet')}
async function backupImport(data){if(data.kind!=='fusion-world-collector-backup'||data.schema_version!==1||!Array.isArray(data.ownedIds)||!Array.isArray(data.favorites))throw Error('Kein kompatibles Fusion-World-Backup');if(data.ownedIds.some(id=>typeof id!=='string')||data.favorites.some(id=>typeof id!=='string'))throw Error('Falsche Karten-IDs');let c=data.catalogSnapshot?normalizeCatalog(data.catalogSnapshot):null;if(!confirm(`Backup vom ${data.created_at||'unbekannt'} importieren? Deine aktuellen Haken und die Wunschliste werden ersetzt.`))return;const extra=normalizeExtras(data);Object.assign(state,extra);state.marketPrices=normalizeMarketPrices(data.marketPrices);state.marketPriceUpdated=String(data.marketPriceUpdated||'');state.marketPriceUrl=String(data.marketPriceUrl||'');state.marketPriceChecked=String(data.marketPriceChecked||'');state.marketPriceStats=data.marketPriceStats&&typeof data.marketPriceStats==='object'?data.marketPriceStats:{};state.ownedIds=unique(data.ownedIds);state.favorites=unique(data.favorites);state.localCards=Array.isArray(data.localCards)?data.localCards:[];state.catalogOverride=c?{...c,cards:c.cards.filter(item=>!window.FW_CATALOG.cards.some(current=>current.id===item.id))}:state.catalogOverride;state.preimport=Array.isArray(data.preimport)?data.preimport:[];state.unbackedAdds=[];state.lastBackup=data.created_at||new Date().toISOString();state.seedApplied=true;rebuild();save();render();notify('Backup importiert – Sammlung wiederhergestellt')}
// Explicit TCGplayer product IDs are edition-specific. Never infer IDs from printed card numbers.
// Expand this verified mapping as the source feed supplies validated IDs for other sets.
const TCGPLAYER_PRODUCT_IDS={'FB08-121#ALT-2':666774};
async function loadVerifiedProductIds(){try{const r=await fetch('./tcgplayer-product-ids.json',{cache:'no-store'});if(!r.ok)return;const payload=await r.json();if(!payload||!payload.ids||typeof payload.ids!=='object')return;for(const [id,value] of Object.entries(payload.ids)){const n=Number(value);if(cardById.has(id)&&Number.isInteger(n)&&n>0)TCGPLAYER_PRODUCT_IDS[id]=n}}catch(e){console.warn('TCGplayer product ID map not available',e)}}
function tcgProductId(card){return Number(card?.tcgplayer_product_id||TCGPLAYER_PRODUCT_IDS[card?.id])||null}
function productIdIndex(){const index=new Map(),ambiguous=new Set();for(const c of cards){const id=tcgProductId(c);if(!id)continue;if(index.has(id)){ambiguous.add(id);continue}index.set(id,c.id)}for(const id of ambiguous)index.delete(id);return index}
function normalizePriceFeed(feed){
 if(!feed||feed.kind!=='fusion-world-market-prices'||feed.schema_version!==1||!feed.prices||Array.isArray(feed.prices)||typeof feed.prices!=='object')throw Error('Keine kompatible Fusion-World-Preisdatei');
 if(Object.keys(feed.prices).length>30000)throw Error('Preisdatei zu groß');
 const incoming={},unknown=[],conflicts=[];const byProductId=productIdIndex();
 for(const [rawId,item] of Object.entries(feed.prices)){
  const urlProductId=typeof item?.url==='string'?Number(item.url.match(/\/product\/(\d+)(?:\/|\?|$)/)?.[1]||0):0;
  const productId=Number(item?.tcgplayer_product_id||item?.product_id||item?.productId||urlProductId||(/^\d+$/.test(rawId)?rawId:0));
  const mapped=productId?byProductId.get(productId):null;
  // Product ID wins over ambiguous printed card numbers; reject contradictory matches.
  if(mapped&&cardById.has(rawId)&&mapped!==rawId){conflicts.push(rawId);continue}
  const id=mapped||(cardById.has(rawId)?rawId:null);
  if(!id){unknown.push(rawId);continue}
  const expected=tcgProductId(cardById.get(id));
  if(expected&&productId&&expected!==productId){conflicts.push(rawId);continue}
  const val=typeof item==='number'?item:item?.amount;
  if(typeof val!=='number'||!Number.isFinite(val)||val<0||val>1000000)continue;
  const url=typeof item==='object'&&item?.url&&/^https:\/\/(www\.)?tcgplayer\.com\//i.test(item.url)?item.url:'';
  incoming[id]={amount:Math.round(val*100)/100,date:String(item?.date||feed.updated_at||'').slice(0,10),source:'TCGplayer via TCGCSV',url,productId:productId||expected||null};
 }
 return{incoming,unknown,conflicts,date:String(feed.updated_at||'').slice(0,10),stats:feed.stats||{}};
}
function ingestPrices(feed){const v=normalizePriceFeed(feed),previous=Object.keys(state.marketPrices||{}).length;if(!Object.keys(v.incoming).length)throw Error('Keine zuordenbaren Kartenpreise gefunden');if(previous>=20&&Object.keys(v.incoming).length<previous*0.75)throw Error('Preisfeed enthält deutlich weniger Karten als bisher – alter Preisstand bleibt erhalten');state.marketPrices={...state.marketPrices,...v.incoming};state.marketPriceUpdated=v.date||new Date().toISOString().slice(0,10);state.marketPriceStats={...v.stats,note:`${Object.keys(v.incoming).length} Varianten zugeordnet · ${v.unknown.length} IDs nicht im Katalog · ${v.conflicts.length} widersprüchliche IDs abgelehnt. Vorher ${previous} Preise.`};save();render();notify(`${Object.keys(v.incoming).length} Marktpreise gespeichert`);return v}
async function priceImport(data){const v=normalizePriceFeed(data);if(!Object.keys(v.incoming).length)throw Error('Keine passenden Preise gefunden');if(!confirm(`${Object.keys(v.incoming).length} Kartenpreise mit Stand ${v.date||'unbekannt'} importieren? Bisherige Marktpreise werden ersetzt; manuelle Preise und Besitzdaten bleiben.`))return;ingestPrices(data)}
// If the application is opened on GitHub Pages, its daily generated prices.json
// is available on the same HTTPS origin. No manual URL or CORS proxy is needed.
function autoPriceFeedUrl(){
 try{
  if(location.protocol==='https:' && /^[a-z0-9-]+\.github\.io$/i.test(location.hostname))
   return new URL('./prices.json',location.href).href;
 }catch(e){console.warn('Automatic price feed URL unavailable:',e)}
 return '';
}
